package app.hisn.core;

import java.io.FileInputStream;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;

/**
 * Certificate-name rules for the encrypted resolver. Fixtures are generated by {@code test-core.sh}:
 * a localhost SAN certificate, a wildcard SAN certificate, a certificate with no SAN at all, and a
 * certificate whose only SAN entry is an IP address.
 */
public final class TlsHostnameTest {
    public static void main(String[] args) throws Exception {
        if (args.length != 4) throw new IllegalArgumentException(
                "TlsHostnameTest needs localhost, wildcard, CN-only and IP-SAN certificates");
        X509Certificate localhost = load(args[0]);
        X509Certificate wildcard = load(args[1]);
        X509Certificate cnOnly = load(args[2]);
        X509Certificate ipSan = load(args[3]);

        expect(localhost, "localhost", true);
        expect(localhost, "LOCALHOST", true);
        expect(localhost, "localhost.", true);
        expect(localhost, " wrong.example ", false);
        expect(localhost, "sub.localhost", false);
        expect(localhost, "", false);

        expect(wildcard, "a.wild.example", true);
        expect(wildcard, "A.WILD.EXAMPLE.", true);
        expect(wildcard, "wild.example", false);
        expect(wildcard, "a.b.wild.example", false);
        expect(wildcard, "xwild.example", false);
        expect(wildcard, "a.wild.example.evil", false);
        expect(wildcard, "*.wild.example", false);

        // No subjectAltName at all: the legacy common-name fallback is the only name source.
        expect(cnOnly, "legacy.example", true);
        expect(cnOnly, "LEGACY.EXAMPLE", true);
        expect(cnOnly, "a.legacy.example", false);

        // A subjectAltName with only an IP entry must not fall back to the common name.
        expect(ipSan, "legacy.example", false);
        expect(ipSan, "127.0.0.1", false);

        System.out.println("TlsHostname tests passed (SAN, wildcard, CN fallback and IP-only SAN rules)");
    }

    private static void expect(X509Certificate certificate, String hostname, boolean expected) {
        boolean actual = TlsHostname.matches(hostname, certificate);
        if (actual != expected) throw new AssertionError(
                "TlsHostname.matches(" + hostname + ") was " + actual + ", expected " + expected);
    }

    private static X509Certificate load(String path) throws Exception {
        CertificateFactory factory = CertificateFactory.getInstance("X.509");
        try (FileInputStream input = new FileInputStream(path)) {
            return (X509Certificate) factory.generateCertificate(input);
        }
    }
}
